// ===== CONFIG =====
const ALLOWED_CHAT_ID = '';   // shen telegram chat id (optional)
// ==================
const msg = $input.first().json.message;
if (!msg) return [];
const chat_id = msg.chat.id;
if (ALLOWED_CHAT_ID && String(chat_id) !== String(ALLOWED_CHAT_ID)) return [];
const sd = $getWorkflowStaticData('global');
sd.pending = sd.pending || {};
const raw = (msg.caption || msg.text || '').trim();
let fileId = null;
if (msg.document && ((msg.document.mime_type || '').startsWith('image/') || /\.(jpe?g|png|webp)$/i.test(msg.document.file_name || ''))) fileId = msg.document.file_id;
else if (msg.photo && msg.photo.length) fileId = msg.photo[msg.photo.length - 1].file_id;

const help = 'Send the BACKGROUND image as a FILE (not a compressed photo) with a caption:\n\n' +
  'Single:  Lamine Yamal | I have been at the level to *win Ballon d\'Or* for a longer time\n' +
  'Circle left:  L: Author | quote with *yellow words*  (then send the circle image)\n' +
  'Circle right: R: Author | quote with *yellow words*  (then send the circle image)\n\n' +
  'Crop (optional): [c:50,25,1.3] circle, [b:50,40,1] background = x%,y%,zoom\n' +
  'Optional Instagram caption after ||  e.g.  Author | quote || 🚨 My caption #football';
const out = (o) => [{ json: { chat_id, ready: false, ...o } }];

function parseText(t) {
  const pos = { b: [50, 50, 1], c: [50, 30, 1] };
  t = t.replace(/\[\s*([bcBC])\s*:\s*([\d.]+)\s*,\s*([\d.]+)\s*(?:,\s*([\d.]+))?\s*\]/g, (m, k, x, y, z) => { pos[k.toLowerCase()] = [+x, +y, +(z || 1)]; return ''; });
  let layout = 'single';
  const m = t.match(/^\s*([LRSlrs])\s*:\s*([\s\S]+)$/);
  if (m) { layout = { l: 'left', r: 'right', s: 'single' }[m[1].toLowerCase()]; t = m[2]; }
  let caption = '';
  const ci = t.indexOf('||');
  if (ci >= 0) { caption = t.slice(ci + 2).trim(); t = t.slice(0, ci); }
  let author = '', quote = t.trim();
  const pi = t.indexOf('|');
  if (pi >= 0) { author = t.slice(0, pi).trim(); quote = t.slice(pi + 1).trim(); }
  return { layout, author, quote, caption, pos };
}
const jobItems = (job, bgId, circleId) => {
  const base = { chat_id, ready: true, ...job };
  const items = [{ json: { ...base, role: 'bg', file_id: bgId } }];
  if (job.layout !== 'single' && circleId) items.push({ json: { ...base, role: 'circle', file_id: circleId } });
  return items;
};

if (!fileId) return out({ reply: help });

if (raw) {
  const job = parseText(raw);
  if (job.layout === 'single') { delete sd.pending[chat_id]; return jobItems(job, fileId, null); }
  sd.pending[chat_id] = { job, bg_file_id: fileId };
  return out({ reply: 'Got the background. Now send the CIRCLE image (as a file, no caption).' });
}
const p = sd.pending[chat_id];
if (!p) return out({ reply: help });
delete sd.pending[chat_id];
return jobItems(p.job, p.bg_file_id, fileId);

const meta = $('Parse Message').first().json;
const items = $input.all();
const sniff = (b) => (b[0] === 0x89 && b[1] === 0x50) ? 'image/png' : (b[0] === 0x52 && b[1] === 0x49) ? 'image/webp' : 'image/jpeg';
const uri = async (i) => {
  const b = await this.helpers.getBinaryDataBuffer(i, 'data');
  return 'data:' + sniff(b) + ';base64,' + b.toString('base64');
};
const bg = await uri(0);
const circle = (meta.layout !== 'single' && items[1]) ? await uri(1) : null;
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parts = String(meta.quote || '').split('*');
const quoteHtml = parts.map((p, i) => i % 2 ? '<span class="y">' + esc(p) + '</span>' : esc(p)).join('');
const side = meta.layout === 'left' ? 'left:40px' : 'left:540px';
const circleHtml = circle ? '<div class="circle" style="' + side + '"><img id="ci" src="' + circle + '"></div>' : '';

const html = `<!doctype html><html><head><meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=Anton&family=Montserrat:wght@800&display=block" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:2160px;height:2700px;overflow:hidden;background:#080a10}
.post{width:1080px;height:1350px;transform:scale(2);transform-origin:0 0;position:relative;overflow:hidden;background:#080a10}
.bg{position:absolute;left:0;top:0;max-width:none}
.shade{position:absolute;left:0;right:0;bottom:0;height:750px;background:linear-gradient(to bottom,rgba(8,10,16,0),rgba(8,10,16,.92) 60%,#080a10)}
.circle{position:absolute;top:110px;width:500px;height:500px;border-radius:50%;border:8px solid #fff;overflow:hidden;background:#222}
.circle img{position:absolute;left:0;top:0;max-width:none}
.bottom{position:absolute;left:70px;right:70px;bottom:50px;display:flex;flex-direction:column;align-items:center}
.rule{display:flex;align-items:center;width:100%;padding:0 230px;margin-bottom:30px}
.rule i{flex:1;height:2px;background:rgba(255,255,255,.7)}
.rule b{display:flex;gap:8px;margin:0 10px}
.rule b span{display:block;width:22px;height:16px;background:#fff;transform:skewX(-25deg)}
#q{font-family:Anton,Impact,'Arial Narrow',sans-serif;font-size:96px;line-height:1.06;text-align:center;color:#fff;text-transform:uppercase;text-wrap:balance;width:100%}
.y{color:#f4ff3a}
#a{margin-top:32px;width:100%;text-align:center;white-space:nowrap;font:800 34px Montserrat,Arial,sans-serif;letter-spacing:4px;color:#fff;text-transform:uppercase}
</style></head><body><div class="post">
<img class="bg" id="bgi" src="${bg}">
<div class="shade"></div>
${circleHtml}
<div class="bottom">
<div class="rule"><i></i><b><span></span><span></span><span></span><span></span></b><i></i></div>
<div id="q">${quoteHtml}</div>
<div id="a">${esc(meta.author)}</div>
</div></div>
<script>
var P=${JSON.stringify(meta.pos || {})};
function place(img,box,p){
  var cw=box.clientWidth,ch=box.clientHeight,fx=(p[0]==null?50:p[0])/100,fy=(p[1]==null?50:p[1])/100,z=p[2]||1;
  var s=Math.max(cw/img.naturalWidth,ch/img.naturalHeight)*z,dw=img.naturalWidth*s,dh=img.naturalHeight*s;
  img.style.width=dw+'px';img.style.height=dh+'px';
  img.style.left=Math.min(0,Math.max(cw-dw,cw/2-fx*dw))+'px';
  img.style.top=Math.min(0,Math.max(ch-dh,ch/2-fy*dh))+'px';
}
function ready(i){return i&&i.decode?i.decode().catch(function(){}):Promise.resolve();}
function fit(){
  var q=document.getElementById('q'),a=document.getElementById('a'),fs=96;
  q.style.fontSize=fs+'px';
  function lines(){return Math.round(q.offsetHeight/(fs*1.06));}
  while(fs>40&&(lines()>3||(lines()===3&&fs>82)||q.scrollWidth>q.clientWidth)){fs-=2;q.style.fontSize=fs+'px';}
  var as=34;
  while(as>16&&a.scrollWidth>a.clientWidth){as-=1;a.style.fontSize=as+'px';}
}
var bgi=document.getElementById('bgi'),ci=document.getElementById('ci');
Promise.all([ready(bgi),ready(ci)]).then(function(){
  place(bgi,document.querySelector('.post'),P.b||[50,50,1]);
  if(ci)place(ci,ci.parentNode,P.c||[50,30,1]);
}).then(function(){return document.fonts.load('130px Anton');})
.then(function(){return document.fonts.load('800 34px Montserrat');}).then(fit,fit);
</script></body></html>`;

const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{ json: { chat_id: meta.chat_id }, binary: { data: bin } }];

const items = $input.all();
items[0].binary.data.fileName = 'news-post.png';
items[0].binary.data.mimeType = 'image/png';
items[0].binary.data.fileExtension = 'png';
return items;
